# Generated by GitHub Copilot - Nov-17-2026
"""Editable Word (DOCX) export of the rich resume model, styled to match each HTML template.

Contact/meta icons and the initials avatar are embedded PNGs (see docx_assets) so the document looks the
same on every machine; contact links are real hyperlinks (http(s)/mailto/tel only).
"""
import io
import re

from docx import Document
from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_TABLE_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_TAB_ALIGNMENT
from docx.opc.constants import RELATIONSHIP_TYPE as RT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Mm, Pt, RGBColor

from .docx_assets import avatar_png, icon_png
from .lang_data import detect_language
from .render_html import SAFE_HREF, display_case, initials
from .resume_model import bold_keywords_for, build_model, segments
from .resume_templates import SIDEBAR_KEYS, resolve

INK, MUTED, WHITE, RULE = (31, 35, 40), (91, 98, 112), (255, 255, 255), "C9CED6"
SCRIPT_FONT = {"zh": "Microsoft YaHei", "hi": "Nirmala UI", "ar": "Arial"}
PAGE_W_MM, MARGIN_MM = 210, 14
ACCENT_SUBTITLE = {"professional", "modern", "technical", "creative", "elegant", "executive", "timeline", "compact"}
ICON_TEMPLATES = {"classic", "professional", "modern", "executive", "creative", "technical", "elegant", "compact",
                  "timeline"}


def _rgb(hex_color: str) -> tuple[int, int, int]:
    return tuple(int(hex_color[i:i + 2], 16) for i in (1, 3, 5))


def _hex(rgb) -> str:
    return "%02X%02X%02X" % tuple(rgb)


def _tint(rgb, amount: float) -> tuple[int, int, int]:
    return tuple(int(c + (255 - c) * amount) for c in rgb)


class Writer:
    """Writes styled paragraphs into a document body or a table cell."""

    def __init__(self, container, width_mm: float, font: str, accent, tpl: dict, tpl_id: str, rtl: bool,
                 keywords, inverse=False):
        self.c, self.width, self.font, self.accent = container, width_mm, font, accent
        self.tpl, self.tpl_id, self.rtl, self.kw, self.inverse = tpl, tpl_id, rtl, keywords, inverse
        self.body = 9.5 if tpl.get("dense") else 10.5 if tpl_id in ("classic", "modern") else 10
        self.ink = WHITE if inverse else INK
        self.muted = (235, 232, 245) if inverse else MUTED
        self.in_cell = not hasattr(container, "add_section")
        self._fresh_cell = self.in_cell

    # ------------------------------------------------------------------ primitives
    def para(self, align=None, before=0.0, after=1.5, keep=False):
        if self._fresh_cell:
            p = self.c.paragraphs[0]  # every new table cell starts with one empty paragraph
            self._fresh_cell = False
        else:
            p = self.c.add_paragraph()
        fmt = p.paragraph_format
        # keep_with_next inside a table cell makes Word push the whole row to the next page
        fmt.space_before, fmt.space_after = Pt(before), Pt(after)
        fmt.keep_with_next = keep and not self.in_cell
        p.alignment = align if align is not None else (WD_ALIGN_PARAGRAPH.RIGHT if self.rtl else WD_ALIGN_PARAGRAPH.LEFT)
        if self.rtl:
            p._p.get_or_add_pPr().append(OxmlElement("w:bidi"))
        return p

    def bullet(self):
        if self._fresh_cell:
            p = self.c.paragraphs[0]
            p.style = self.c.part.document.styles["List Bullet"]
            self._fresh_cell = False
        else:
            p = self.c.add_paragraph(style="List Bullet")
        p.paragraph_format.space_after = Pt(1)
        if self.rtl:
            p._p.get_or_add_pPr().append(OxmlElement("w:bidi"))
        return p

    def run(self, p, text, size=None, bold=False, italic=False, color=None, caps=False, small_caps=False,
            font=None, shade=None):
        r = p.add_run(text)
        f = r.font
        f.name, f.size, f.bold, f.italic = font or self.font, Pt(size or self.body), bold, italic
        f.all_caps, f.small_caps = caps, small_caps
        f.color.rgb = RGBColor(*(color or self.ink))
        rpr = r._element.get_or_add_rPr()
        fonts = rpr.find(qn("w:rFonts"))
        if fonts is None:
            fonts = OxmlElement("w:rFonts")
            rpr.insert(0, fonts)
        for attr in ("w:ascii", "w:hAnsi", "w:eastAsia", "w:cs"):
            fonts.set(qn(attr), font or self.font)
        if shade:
            shd = OxmlElement("w:shd")
            for k, v in (("w:val", "clear"), ("w:color", "auto"), ("w:fill", shade)):
                shd.set(qn(k), v)
            rpr.append(shd)
        if self.rtl:
            rpr.append(OxmlElement("w:rtl"))
        return r

    def rich(self, p, text, size=None, italic=False, color=None):
        for chunk, bold in segments(text, self.kw):
            self.run(p, chunk, size=size, bold=bold, italic=italic, color=color)

    def picture(self, p, png: bytes, height_pt: float, lower_pt: float = 0.0):
        r = p.add_run()
        r.add_picture(io.BytesIO(png), height=Pt(height_pt))
        if lower_pt:
            pos = OxmlElement("w:position")
            pos.set(qn("w:val"), str(int(-lower_pt * 2)))  # half-points; negative lowers the image
            r._element.get_or_add_rPr().append(pos)
        return r

    def link(self, p, href: str, text: str, **style):
        """Clickable hyperlink (only http(s)/mailto/tel)."""
        if not href or not SAFE_HREF.match(href):
            return self.run(p, text, **style)
        r_id = p.part.relate_to(href, RT.HYPERLINK, is_external=True)
        hl = OxmlElement("w:hyperlink")
        hl.set(qn("r:id"), r_id)
        r = self.run(p, text, **style)
        p._p.remove(r._r)
        hl.append(r._r)
        p._p.append(hl)
        return r

    def right_tab(self, p):
        p.paragraph_format.tab_stops.add_tab_stop(Mm(self.width), WD_TAB_ALIGNMENT.RIGHT)

    @staticmethod
    def border(p, side: str, color: str, size: int = 8, space: int = 1, val: str = "single"):
        ppr = p._p.get_or_add_pPr()
        bdr = ppr.find(qn("w:pBdr"))
        if bdr is None:
            bdr = OxmlElement("w:pBdr")
            ppr.append(bdr)
        el = OxmlElement(f"w:{side}")
        for k, v in (("w:val", val), ("w:sz", str(size)), ("w:space", str(space)), ("w:color", color)):
            el.set(qn(k), v)
        bdr.append(el)

    @staticmethod
    def shade(p, fill: str):
        shd = OxmlElement("w:shd")
        for k, v in (("w:val", "clear"), ("w:color", "auto"), ("w:fill", fill)):
            shd.set(qn(k), v)
        p._p.get_or_add_pPr().append(shd)

    # ------------------------------------------------------------------ blocks
    def contacts(self, contacts: list[dict], align=None, size=9.0, bold=False, color=None, icon_color=None,
                 stacked=False, after=4.0):
        """Contact row (or column) with PNG icons, like the HTML templates."""
        color = color or self.muted
        use_icons = self.tpl_id in ICON_TEMPLATES
        sep = "  ·  " if not use_icons else "     "
        p = None
        for i, c in enumerate(contacts):
            if p is None or stacked:
                p = self.para(align=align, after=after if not stacked else 2.5)
            elif not use_icons:
                self.run(p, sep, size=size, color=color)
            else:
                self.run(p, sep, size=size)
            if use_icons:
                self.picture(p, icon_png(c["kind"], tuple(icon_color or self.accent)), size * 0.95, lower_pt=1)
                self.run(p, " ", size=size)
            self.link(p, c.get("href", ""), c["text"], size=size, bold=bold, color=color)
        return p

    def heading(self, text: str):
        style = self.tpl["heading"]
        accent = WHITE if self.inverse else self.accent
        center = WD_ALIGN_PARAGRAPH.CENTER if style == "centered" else None
        p = self.para(align=center, before=10 if not self.tpl.get("dense") else 6, after=3.5, keep=True)
        size = 13.5 if self.tpl_id == "professional" else 10 if self.tpl.get("dense") else 11.5
        color = INK if style == "thick" and not self.inverse else accent
        label = f"{text}" if style != "leftbar" else f" {text}"
        self.run(p, label, size=size, bold=style != "centered", color=color, caps=True)
        if style in ("rule", "accent-rule", "thick"):
            self.border(p, "bottom", _hex(INK if style == "thick" else accent), 20 if style == "thick" else 8, 2)
        elif style == "leftbar":
            self.border(p, "right" if self.rtl else "left", _hex(accent), 36, 4)
            self.shade(p, _hex(_tint(accent, 0.88)))
        elif style == "centered":
            self.border(p, "bottom", _hex(accent), 4, 2)
        elif style == "accent" and self.tpl_id == "creative" and not self.inverse:
            self.border(p, "bottom", _hex(_tint(accent, 0.6)), 8, 2)
        elif style == "accent" and self.inverse:
            self.border(p, "bottom", "FFFFFF", 6, 2)

    def entry(self, e: dict, stacked: bool, first: bool, dates_elsewhere: bool = False):
        accent = WHITE if self.inverse else self.accent
        p = self.para(before=3 if first else 5, after=0.5, keep=True)
        if stacked and not first:
            self.border(p, "top", RULE, 6, 6, val="dashed")
        self.run(p, e["title"], size=self.body + 1 if stacked else self.body + 0.5, bold=True)
        if e["meta"]:
            self.run(p, f"  |  {e['meta']}")
        if dates_elsewhere:
            if e["subtitle"]:
                self.run(self.para(after=1, keep=True), e["subtitle"], bold=True)
        elif stacked:
            if e["subtitle"]:
                self.run(self.para(after=0.5, keep=True), e["subtitle"], bold=True, color=accent)
            if e["date"] or e["location"]:
                ip = self.para(after=1.5, keep=True)
                icon_color = self.muted
                if e["date"]:
                    self.picture(ip, icon_png("calendar", tuple(icon_color)), self.body - 1.5, lower_pt=1)
                    self.run(ip, " " + e["date"] + ("      " if e["location"] else ""), size=self.body - 1, color=self.muted)
                if e["location"]:
                    self.picture(ip, icon_png("location", tuple(icon_color)), self.body - 1.5, lower_pt=1)
                    self.run(ip, " " + e["location"], size=self.body - 1, color=self.muted)
        else:
            if e["date"]:
                self.right_tab(p)
                self.run(p, "\t" + e["date"], color=accent if self.tpl_id == "timeline" else None,
                         bold=self.tpl_id == "timeline")
            if e["subtitle"] or e["location"]:
                p2 = self.para(after=1, keep=True)
                sub_accent = self.tpl_id in ACCENT_SUBTITLE
                self.run(p2, e["subtitle"], italic=not sub_accent, bold=sub_accent,
                         color=accent if sub_accent else None)
                if e["location"]:
                    self.right_tab(p2)
                    self.run(p2, "\t" + e["location"], italic=True, color=self.muted)
        for d in e["details"]:
            self.rich(self.para(after=1), d, italic=True)
        for b in e["bullets"]:
            self.rich(self.bullet(), b)
        if e["tech"]:
            tp = self.para(before=1, after=2)
            self.run(tp, e["tech"]["label"] + ": ", bold=True, italic=True)
            self.run(tp, e["tech"]["value"], italic=True)
        if e["link"]:
            lp = self.para(after=2)
            self.link(lp, e["link"], e["link"], size=self.body - 1.5, color=self.muted)

    def skills(self, groups: list[dict], stacked: bool):
        accent = WHITE if self.inverse else self.accent
        chips = self.tpl_id == "technical" or (self.tpl_id == "creative" and self.inverse)
        for i, g in enumerate(groups):
            if stacked and g["label"]:
                self.run(self.para(before=3, after=0.5, keep=True), g["label"], bold=True, color=accent)
                ip = self.para(after=3)
                self._skill_items(ip, g["items"], chips)
                if self.tpl_id == "professional" and i < len(groups) - 1:
                    self.border(ip, "bottom", RULE, 6, 4, val="dashed")
                continue
            p = self.para(after=1.5)
            if g["label"]:
                label_color = accent if self.tpl_id in ("modern", "elegant", "executive", "technical", "creative") else None
                self.run(p, g["label"] + (" : " if self.tpl_id == "classic" else ": "), bold=True, color=label_color)
            self._skill_items(p, g["items"], chips)

    def _skill_items(self, p, items, chips: bool):
        if not chips:
            self.run(p, ", ".join(items))
            return
        fill = _hex(_tint(self.accent, 0.86)) if not self.inverse else _hex(_tint(self.accent, 0.25))
        color = self.accent if not self.inverse else WHITE
        for i, item in enumerate(items):
            self.run(p, f"\u00a0{item}\u00a0", size=self.body - 1, bold=True, color=color, shade=fill)
            if i < len(items) - 1:
                self.run(p, "  ", size=self.body - 1)

    def section(self, sec: dict, stacked: bool, show_heading: bool = True):
        if sec.get("heading") and show_heading:
            self.heading(display_case(sec["heading"]))
        if sec["kind"] == "entries" and self.tpl_id == "timeline" and not self.in_cell:
            self._timeline(sec["entries"])
        elif sec["kind"] == "entries":
            for i, e in enumerate(sec["entries"]):
                self.entry(e, stacked, first=i == 0)
        elif sec["kind"] == "skills":
            self.skills(sec["groups"], stacked)
        elif sec["kind"] == "list":
            for item in sec["items"]:
                self.rich(self.bullet(), item)
        else:
            for para in sec["paragraphs"]:
                self.rich(self.para(after=2), para)

    def _timeline(self, entries: list[dict]):
        """Dates in a left rail, entry content to the right of an accent line (Timeline template)."""
        rail = 35
        table = _table(self.c, [rail, self.width - rail])
        for i, e in enumerate(entries):
            row = table.rows[0] if i == 0 else table.add_row()
            left, right = row.cells
            left.width, right.width = Mm(rail), Mm(self.width - rail)
            _cell_border(right, "right" if self.rtl else "left", _hex(_tint(self.accent, 0.75)), 16)
            _cell_margins(right, 0)
            for side in ("left", "start") if not self.rtl else ("right", "end"):
                right._tc.tcPr.find(qn("w:tcMar")).find(qn(f"w:{side}")).set(qn("w:w"), str(int(5 * 56.7)))
            lw = Writer(left, rail - 2, self.font, self.accent, self.tpl, self.tpl_id, self.rtl, self.kw)
            end = WD_ALIGN_PARAGRAPH.LEFT if self.rtl else WD_ALIGN_PARAGRAPH.RIGHT
            if e["date"]:
                lw.run(lw.para(align=end, before=3, after=0.5), e["date"], size=self.body - 1, bold=True, color=self.accent)
            if e["location"]:
                lw.run(lw.para(align=end, after=0), e["location"], size=self.body - 1.5, color=MUTED)
            rw = Writer(right, self.width - rail - 6, self.font, self.accent, self.tpl, self.tpl_id, self.rtl, self.kw)
            rw.entry(e, stacked=False, first=True, dates_elsewhere=True)
            rw.run(rw.para(after=2), "", size=2)
        self.para(after=0)


def _cell_border(cell, side: str, color: str, size: int):
    borders = cell._tc.get_or_add_tcPr().find(qn("w:tcBorders"))
    if borders is None:
        borders = OxmlElement("w:tcBorders")
        cell._tc.get_or_add_tcPr().append(borders)
    el = OxmlElement(f"w:{side}")
    for k, v in (("w:val", "single"), ("w:sz", str(size)), ("w:space", "0"), ("w:color", color)):
        el.set(qn(k), v)
    borders.append(el)


# ---------------------------------------------------------------------- document helpers
def _no_borders(table):
    borders = OxmlElement("w:tblBorders")
    for side in ("top", "left", "bottom", "right", "insideH", "insideV"):
        el = OxmlElement(f"w:{side}")
        el.set(qn("w:val"), "nil")
        borders.append(el)
    table._tbl.tblPr.append(borders)


def _cell_shading(cell, fill: str):
    shd = OxmlElement("w:shd")
    for k, v in (("w:val", "clear"), ("w:color", "auto"), ("w:fill", fill)):
        shd.set(qn(k), v)
    cell._tc.get_or_add_tcPr().append(shd)


def _cell_margins(cell, mm_each: float):
    mar = OxmlElement("w:tcMar")
    for side in ("top", "start", "bottom", "end", "left", "right"):
        el = OxmlElement(f"w:{side}")
        el.set(qn("w:w"), str(int(mm_each * 56.7)))
        el.set(qn("w:type"), "dxa")
        mar.append(el)
    cell._tc.get_or_add_tcPr().append(mar)


def _table(doc_or_cell, widths_mm: list[float]):
    table = doc_or_cell.add_table(rows=1, cols=len(widths_mm))
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    table.autofit = False
    _no_borders(table)
    for cell, w in zip(table.rows[0].cells, widths_mm):
        cell.width = Mm(w)
    return table


def _modern_compat(doc):
    """Mark the file as Word 2013+ so it does not open in 'Compatibility Mode'."""
    settings = doc.settings.element
    compat = settings.find(qn("w:compat"))
    if compat is None:
        compat = OxmlElement("w:compat")
        settings.append(compat)
    for el in compat.findall(qn("w:compatSetting")):
        if el.get(qn("w:name")) == "compatibilityMode":
            el.set(qn("w:val"), "15")
            return
    el = OxmlElement("w:compatSetting")
    for k, v in (("w:name", "compatibilityMode"), ("w:uri", "http://schemas.microsoft.com/office/word"),
                 ("w:val", "15")):
        el.set(qn(k), v)
    compat.append(el)


# ---------------------------------------------------------------------- export
def export_docx(text: str, template: str = "modern", accent: str | None = None, bold_keywords: bool = False,
                job_description: str = "", lang: str | None = None) -> bytes:
    """Build a styled, editable DOCX that mirrors the chosen HTML template."""
    tpl, _, accent_hex = resolve(template, accent)
    accent_rgb = _rgb(accent_hex)
    lang = lang or detect_language(text)
    rtl = lang == "ar"
    font = SCRIPT_FONT.get(lang, tpl["font"])
    model = build_model(text)
    kw = bold_keywords_for(text, job_description) if bold_keywords else None

    doc = Document()
    _modern_compat(doc)
    section = doc.sections[0]
    section.page_width, section.page_height = Mm(PAGE_W_MM), Mm(297)
    section.left_margin = section.right_margin = Mm(MARGIN_MM)
    section.top_margin = section.bottom_margin = Mm(12)
    normal = doc.styles["Normal"]
    normal.font.name, normal.font.size = font, Pt(10)
    content_w = PAGE_W_MM - 2 * MARGIN_MM
    w = Writer(doc, content_w, font, accent_rgb, tpl, template, rtl, kw)

    name = display_case(model["name"]) or "Resume"
    header_style = tpl["header"]
    center = WD_ALIGN_PARAGRAPH.CENTER if header_style == "center" else None
    banner = header_style == "banner"
    name_color = WHITE if banner else INK if template in ("classic", "professional", "minimal") else accent_rgb
    name_size = {"classic": 27, "professional": 27, "minimal": 30, "compact": 20, "elegant": 28,
                 "creative": 28, "modern": 28}.get(template, 26)
    head_color = ((219, 228, 239) if banner else accent_rgb if template in ("professional", "compact", "technical")
                  else MUTED)

    def header_block(writer: Writer, align=None):
        p = writer.para(align=align, after=1)
        if template == "technical":
            writer.run(p, "> ", size=name_size, bold=True, color=accent_rgb, font="Consolas")
        writer.run(p, name, size=name_size,
                   bold=template not in ("classic", "minimal", "elegant"),
                   color=name_color, caps=template in ("professional", "elegant"), small_caps=template == "classic",
                   font="Consolas" if template == "technical" else None)
        if model["headline"]:
            hp = writer.para(align=align, after=2)
            writer.run(hp, model["headline"], size=13 if template == "professional" else 12,
                       italic=template in ("classic", "elegant", "executive"),
                       bold=template in ("professional", "compact", "technical"), color=head_color,
                       caps=template in ("minimal", "creative"))
        return p

    layout = tpl["layout"]
    if layout == "single":
        if banner:
            # full-bleed banner: a one-cell table pulled out to the page edges, padded back to the margin
            table = doc.add_table(rows=1, cols=1)
            _no_borders(table)
            ind = OxmlElement("w:tblInd")
            ind.set(qn("w:w"), str(-int(MARGIN_MM * 56.7)))
            ind.set(qn("w:type"), "dxa")
            table._tbl.tblPr.append(ind)
            cell = table.rows[0].cells[0]
            cell.width = Mm(PAGE_W_MM)
            _cell_shading(cell, accent_hex[1:])
            _cell_margins(cell, 3)
            for side in ("left", "right", "start", "end"):
                mar = cell._tc.tcPr.find(qn("w:tcMar")).find(qn(f"w:{side}"))
                mar.set(qn("w:w"), str(int(MARGIN_MM * 56.7)))
            bw = Writer(cell, content_w, font, accent_rgb, tpl, template, rtl, kw)
            header_block(bw)
            bw.contacts(model["contacts"], color=(238, 242, 247), icon_color=(238, 242, 247), after=2)
            w.run(w.para(after=4), " ", size=4)
        else:
            first = header_block(w, center)
            if template == "elegant":
                Writer.border(first, "top", _hex(accent_rgb), 12, 6, val="double")
            last = w.contacts(model["contacts"], align=center, after=6)
            if template == "elegant" and last is not None:
                Writer.border(last, "bottom", _hex(accent_rgb), 12, 6, val="double")
            if template in ("minimal", "compact") and last is not None:
                Writer.border(last, "bottom", _hex(accent_rgb if template == "compact" else (201, 206, 214)),
                              12 if template == "compact" else 6, 6)
        if template == "minimal":
            # section labels in a narrow left column, content on the right (like the HTML template)
            label_w = 30
            table = _table(doc, [label_w, content_w - label_w])
            for i, s in enumerate(model["sections"]):
                row = table.rows[0] if i == 0 else table.add_row()
                left, right = row.cells
                left.width, right.width = Mm(label_w), Mm(content_w - label_w)
                lw = Writer(left, label_w - 2, font, accent_rgb, tpl, template, rtl, kw)
                lp = lw.para(before=6, after=0)
                lw.run(lp, display_case(s.get("heading") or "").upper(), size=8, bold=True, color=accent_rgb)
                lp.paragraph_format.line_spacing = 1.3
                rw = Writer(right, content_w - label_w - 4, font, accent_rgb, tpl, template, rtl, kw)
                rw.section(s, stacked=False, show_heading=False)
                rw.run(rw.para(after=6), "", size=2)
        else:
            for s in model["sections"]:
                w.section(s, stacked=False)
    elif layout == "sidebar-right":
        # header row: name/headline/contacts on the left, initials avatar on the right
        head = _table(doc, [content_w - 40, 40])
        left, right = head.rows[0].cells
        hw = Writer(left, content_w - 44, font, accent_rgb, tpl, template, rtl, kw)
        header_block(hw)
        hw.contacts(model["contacts"], size=9, bold=True, color=INK, after=0)
        right.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
        ap = right.paragraphs[0]
        ap.alignment = WD_ALIGN_PARAGRAPH.LEFT if rtl else WD_ALIGN_PARAGRAPH.RIGHT
        ap.add_run().add_picture(io.BytesIO(avatar_png(initials(name), accent_rgb, WHITE)), height=Mm(30))
        w.run(w.para(after=4), " ", size=4)
        side_w, gap = 62, 8
        main_w = content_w - side_w - gap
        body = _table(doc, [main_w, gap, side_w])
        main_cell, _, side_cell = body.rows[0].cells
        mw = Writer(main_cell, main_w - 2, font, accent_rgb, tpl, template, rtl, kw)
        sw = Writer(side_cell, side_w - 2, font, accent_rgb, tpl, template, rtl, kw)
        for s in model["sections"]:
            to_side = s["key"] in SIDEBAR_KEYS or s["kind"] in ("skills", "list")
            (sw if to_side else mw).section(s, stacked=True)
    else:  # sidebar-left (creative)
        side_w = 64
        main_w = content_w - side_w
        body = _table(doc, [side_w, main_w])
        side_cell, main_cell = body.rows[0].cells
        if rtl:
            side_cell, main_cell = main_cell, side_cell
        _cell_shading(side_cell, accent_hex[1:])
        _cell_margins(side_cell, 4)
        _cell_margins(main_cell, 4)
        sw = Writer(side_cell, side_w - 10, font, accent_rgb, tpl, template, rtl, kw, inverse=True)
        mw = Writer(main_cell, main_w - 10, font, accent_rgb, tpl, template, rtl, kw)
        ap = sw.para(align=WD_ALIGN_PARAGRAPH.CENTER, before=4, after=8)
        ap.add_run().add_picture(io.BytesIO(avatar_png(initials(name), WHITE, accent_rgb,
                                                       ring=(*_tint(accent_rgb, 0.45), 255))), height=Mm(32))
        sw.contacts(model["contacts"], size=8.8, color=WHITE, icon_color=WHITE, stacked=True)
        header_block(mw)
        for s in model["sections"]:
            to_side = s["key"] in SIDEBAR_KEYS or s["kind"] in ("skills", "list")
            (sw if to_side else mw).section(s, stacked=to_side)

    doc.core_properties.title = name
    doc.core_properties.author = re.sub(r"[\r\n]", " ", name)
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()
